mapper.select:
select wr.report_id, wr.household_id, wr.site_id, wr.user_id, wr.dong, wr.ho, wr.head_name, date_format(wr.install_date, '%Y-%m-%d') as install_date, date_format(wr.report_time, '%Y-%m-%d %H:%i') as report_time, wr.reporter_name, wr.confirmer_name, wr.confirmer_signature, wr.photo_door, wr.photo_before1, wr.photo_after1, wr.photo_before2, wr.photo_after2, wr.`status`, wr.remarks, wr.fix_reason, wr.create_time, wr.last_update, s.name as site_name, s.sido, s.sigungu, s.eupmyeondong, s.address from work_report wr left join site s on wr.site_id = s.site_id where wr.delete_flg = 0
and s.sido = #{sido}
and ( s.sigungu = #{sigungu} or s.sigungu like concat(#{sigungu}, '%') or #{sigungu} like concat(s.sigungu, '%') )
and s.eupmyeondong like concat('%', #{eupmyeondong}, '%')
and wr.status = #{status}
and wr.install_date >= #{installStartDate}
and wr.install_date <= #{installEndDate}
and wr.report_time >= concat(#{reportStartDate}, ' 00:00:00')
and wr.report_time <= concat(#{reportEndDate}, ' 23:59:59')
and ( s.name like concat('%', #{query}, '%') or wr.dong like concat('%', #{query}, '%') or concat(wr.dong, '동') like concat('%', #{query}, '%') or wr.ho like concat('%', #{query}, '%') or concat(wr.ho, '호') like concat('%', #{query}, '%') or wr.reporter_name like concat('%', #{query}, '%') or wr.head_name like concat('%', #{query}, '%') )
and wr.user_id = #{userId}
and wr.site_id = #{siteId}
order by wr.report_time desc, wr.create_time desc
